from typing import Callable, Dict, List, Sequence, Tuple

def lawvere_fixed_point(codes: Sequence[int], f: Callable[[int, int], int],
                        g: Callable[[int], int]) -> Tuple[int, int]:
    """Construct the fixed point forced by a point-surjective self-model.
    The diagonal behaviour d(x) = g(f(x)(x)) is named by some code a;
    then b = f(a)(a) satisfies g(b) = b."""
    diagonal = lambda x: g(f(x, x))
    for a in codes:
        if all(f(a, x) == diagonal(x) for x in codes):
            b = f(a, a)
            assert g(b) == b
            return a, b
    raise ValueError("not point-surjective for this diagonal")

def demo() -> None:
    codes = [0, 1, 2]
    g = lambda b: (b * b) % 3          # fixed points 0 and 1
    table: Dict[Tuple[int, int], int] = {}
    for x in codes:
        table[(1, x)] = (x + 1) % 3
        table[(2, x)] = (2 * x) % 3
    for x in codes:
        if x != 0:
            table[(0, x)] = g(table[(x, x)])
    table[(0, 0)] = 0
    f = lambda a, x: table[(a, x)]
    a, b = lawvere_fixed_point(codes, f, g)
    print(f"code a naming diagonal = {a}; forced fixed point b = {b}; g(b) = {g(b)}")

if __name__ == "__main__":
    demo()

from itertools import product
from typing import Callable, List, Sequence

def diagonal_is_unrepresentable(f: Callable[[int, int], bool],
                                codes: Sequence[int]) -> bool:
    """d(x) = not f(x)(x) equals no row f(a, .) of the self-model."""
    d = [not f(x, x) for x in codes]
    return all([f(a, x) for x in codes] != d for a in codes)

def demo() -> None:
    for n in (1, 2, 3):
        codes = list(range(n))
        ok = True
        for bits in product([False, True], repeat=n * n):
            grid = {(a, x): bits[a * n + x] for a in codes for x in codes}
            f = lambda a, x, _g=grid: _g[(a, x)]
            if not diagonal_is_unrepresentable(f, codes):
                ok = False; break
        print(f"n={n}: diagonal missing in every boolean self-model = {ok}")

if __name__ == "__main__":
    demo()

from itertools import product
from typing import Callable, Optional, Sequence

def is_asymmetric(V: Sequence[int], R: Callable[[int, int], bool]) -> bool:
    return all(not (R(a, b) and R(b, a)) for a in V for b in V)

def shortest_loop_length(V: Sequence[int], R: Callable[[int, int], bool],
                         max_len: int = 7) -> Optional[int]:
    for n in range(1, max_len + 1):
        for seq in product(V, repeat=n):
            if all(R(seq[i], seq[(i + 1) % n]) for i in range(n)):
                return n
    return None

def demo() -> None:
    for n in range(3, 7):
        V = list(range(n))
        R = lambda a, b, _n=n: b == (a + 1) % _n
        print(f"Z/{n}Z successor: asymmetric={is_asymmetric(V, R)}, "
              f"shortest loop={shortest_loop_length(V, R, n + 1)}")
    lt = lambda a, b: a < b
    print(f"strict '<': shortest loop={shortest_loop_length([0,1,2,3], lt)} (None=no loop)")

if __name__ == "__main__":
    demo()

